import std/unittest
import std/random
import std/sequtils

suite "Filter Properties":
  test "Filtered length is bounded":
    randomize()
    for _ in 1..30:
      var s = newSeq[int](rand(10..20))
      for i in 0..<s.len: s[i] = rand(100)

      let filtered = s.filterIt(it mod 2 == 0)
      check filtered.len <= s.len

when isMainModule:
  echo "Filter length property tested."

proc safeArrayAccess[N: static[int]](arr: array[N, int], index: static[int]): int =
  when index < 0 or index >= N:
    {.error: "Index out of bounds at compile time".}
  else:
    result = arr[index]

when isMainModule:
  let data = [10, 20, 30]
  let val = safeArrayAccess(data, 1)
  echo "Compile-time checked access: ", val
